    () => sortG('Разложи по трём группам', [g('Живая природа 🌱', LIVE.map(lbl)), g('Неживая природа 🪨', NONLIVE.map(lbl)), g('Рукотворный мир 🛠️', MANMADE.map(lbl))], 3, { explain: 'Природа бывает живая и неживая, а вещи создал человек.' }),
    () => order('Расставь по порядку: как растёт растение', ['семя', 'росток', 'растение с листьями', 'цветок', 'плод с семенами'], { visual: V.big('🌱'), explain: 'Из семени — росток, потом листья, цветок и плод с новыми семенами.' }),
    () => order('Расставь по порядку: как растёт курица', ['яйцо', 'цыплёнок', 'взрослая курица'], { visual: V.big('🐣'), explain: 'Из яйца вылупляется цыплёнок и вырастает в курицу.' }),
    () => input('Всё, что нас окружает и не сделано руками человека, — это… (одно слово)', 'природа', { explain: 'Это природа.' }),
    () => input('Солнце, вода, камни — какая это природа: живая или неживая?', 'неживая', { explain: 'Неживая природа.' }),
    () => input('Растения, животные, грибы — какая это природа?', 'живая', { explain: 'Живая природа.' }),
    () => input('Всё, что сделал человек, называют … мир. Напиши пропущенное слово', 'рукотворный', { explain: 'Рукотворный мир.' }),
    () => choice('Что из этого — неживая природа, хотя и движется?', 'река', ['кошка', 'бабочка', 'человек'], { explain: 'Река течёт, но не дышит и не растёт — это неживая природа.' }),
    () => choice('Без чего живое НЕ может жить?', 'без воздуха, воды, света и тепла', ['без телефона', 'без игрушек', 'без телевизора'], { explain: 'Живому нужны воздух, вода, свет и тепло — всё это даёт неживая природа.' }),
    () => multi('Что сделано человеком?', U.pickN(MANMADE.map(lbl), 3), U.pickN(NATURE.map(lbl), 4), { explain: 'Вещи, дома, машины — рукотворный мир.' }),
    () => choice('Как связаны живая и неживая природа?', 'живое не может жить без солнца, воды и воздуха', ['никак не связаны', 'неживое питается живым', 'живое не нуждается в воде'], { explain: 'Растениям и животным нужны свет, тепло, вода и воздух — это неживая природа.' })
