  const WX_L2 = [
    () => { const gs = U.pickN(SEASON_GROUPS, 2); return sortG('Разложи явления природы по временам года', gs, 3, { explain: 'Листопад и туманы — осенью, снегопады и метели — зимой, капель и ледоход — весной, гроза и радуга — летом.' }); },
    () => match('Соедини условные знаки и погоду', WX_SIGNS, U.rand(4, 5), { explain: 'Условные знаки помогают коротко записать погоду.' }),
    () => { const t = U.rand(1, 25); return choice('Термометр показывает ' + tempSign(-t) + '. Как это прочитать?', tempWord(-t), [tempWord(t), tempWord(-t - 10), tempWord(t + 10)], { explain: 'Знак минус — градусы мороза: ' + tempWord(-t) + '.' }); },
    () => { const t = U.rand(1, 25); return choice('На улице ' + tempWord(t) + '. Как это записать?', tempSign(t), [tempSign(-t), tempSign(t + 10), tempSign(-t - 10)], { explain: 'Тепло записывают со знаком плюс: ' + tempSign(t) + '.' }); },
    () => { const t = U.rand(1, 20); return choice('На улице ' + tempWord(-t) + '. Как это записать?', tempSign(-t), [tempSign(t), tempSign(-t - 5), tempSign(t + 5)], { explain: 'Мороз записывают со знаком минус: ' + tempSign(-t) + '.' }); },
    () => { const p = U.pickN(U.range(-20, -1), 2); const cold = Math.min(p[0], p[1]); return choice('Какая температура <b>холоднее</b>?', tempSign(cold), [tempSign(Math.max(p[0], p[1]))], { explain: 'Чем больше градусов мороза, тем холоднее: ' + tempSign(cold) + '.' }); },
    () => { const w = U.pick(WX_NOT); return choice('Что <b>НЕ</b> относится к погоде?', w, U.pickN(WX_PARTS, 3), { explain: 'Погода — это температура, облачность, осадки и ветер.' }); },
    () => choice('Из чего складывается погода?', 'температура, облачность, осадки, ветер', ['настроение и время', 'день недели и месяц', 'цвет неба и звёзды'], { explain: 'Погода — температура воздуха, облачность, осадки и ветер.' }),
    () => choice('Что означает знак 0° на термометре?', 'граница между теплом и морозом', ['очень жарко', 'термометр сломан', 'сильный мороз'], { explain: 'Ноль градусов — граница: выше — тепло, ниже — мороз.' }),
    () => choice('Небо частично закрыто облаками, солнце то выглядывает, то прячется. Какая погода?', 'переменная облачность ⛅', ['ясно ☀️', 'пасмурно ☁️', 'гроза ⛈️'], { explain: 'Облака есть, но и солнце видно — переменная облачность.' }),
    () => { const p = U.pick(PRECIP); return choice('Что из этого — осадки?', p, U.pickN(NOT_PRECIP, 3), { explain: 'Осадки — вода, которая падает с неба: дождь, снег, град.' }); },
    () => { const n = U.pick(PH_NAMES); const ans = Array.isArray(n[1]) ? n[1][0] : n[1]; return choice('Как называется ' + n[0] + '?', ans, others(PH_NAMES.map(x => Array.isArray(x[1]) ? x[1][0] : x[1]), ans, 3), { explain: U.cap(ans) + ' — ' + n[0] + '.' }); },
    () => choice('Какое явление бывает только весной?', 'ледоход', ['листопад', 'гроза', 'снегопад'], { explain: 'Ледоход — весной лёд на реке ломается и плывёт.' }),
    () => choice('Какое явление бывает осенью?', 'листопад', ['ледоход', 'капель', 'половодье'], { explain: 'Листопад — осеннее явление.' }),
    () => choice('Что показывает термометр?', 'температуру воздуха', ['силу ветра', 'количество осадков', 'время'], { explain: 'Термометр показывает температуру.' }),
    () => choice('Что делает столбик термометра, когда теплеет?', 'поднимается вверх', ['опускается вниз', 'не двигается', 'исчезает'], { explain: 'Чем теплее, тем выше столбик термометра.' })
  ];
  const WX_L3 = [
    () => { const gs = U.pickN(SEASON_GROUPS, 3); return sortG('Разложи явления природы по временам года', gs, 3, { explain: 'У каждого времени года свои явления природы.' }); },
    () => { const n = U.rand(4, 5); const temps = U.pickN(U.range(-20, 25), n).sort((a, b) => a - b); return order('Расставь температуры от самой <b>холодной</b> к самой <b>тёплой</b>', temps.map(tempSign), { visual: V.big('🌡️'), explain: 'Чем больше градусов мороза — тем холоднее, чем больше градусов тепла — тем теплее.' }); },
    () => multi('Из чего складывается погода? Выбери всё', WX_PARTS.slice(), U.pickN(WX_NOT, 3), { explain: 'Погода — температура, облачность, осадки и ветер.' }),
    () => multi('Выбери <b>осадки</b>', U.pickN(PRECIP, 3), U.pickN(NOT_PRECIP, 3), { explain: 'Осадки — дождь, снег, град.' }),
    () => { const s = U.pick(SEASON_GROUPS); const rest = SEASON_GROUPS.filter(x => x !== s).flatMap(x => x.items); return multi('Выбери явления природы, которые бывают: <b>' + s.name + '</b>', U.pickN(s.items, 3), U.pickN(rest, 4), { explain: 'Каждому времени года — свои явления.' }); },
    () => { const n = U.pick(PH_NAMES); return input('Напиши слово: ' + n[0], n[1], { explain: 'Это ' + (Array.isArray(n[1]) ? n[1][0] : n[1]) + '.' }); },
    () => input('Прибор для измерения температуры воздуха (одно слово)', 'термометр', { explain: 'Термометр.' }),
    () => input('Дождь, снег и град — одним словом', 'осадки', { explain: 'Осадки.' }),
    () => { const t = U.rand(1, 20); return input('На термометре ' + tempSign(-t) + '. Сколько градусов мороза?', t, { explain: tempSign(-t) + ' — это ' + tempWord(-t) + '.' }); },
    () => { const a = U.rand(-10, -1), b = U.rand(1, 10); return input('Утром было ' + tempSign(a) + ', а днём стало ' + tempSign(b) + '. На сколько градусов потеплело?', b - a, { explain: 'От ' + tempSign(a) + ' до 0° — ' + (-a) + ' градусов, и ещё ' + b + ' — всего ' + (b - a) + '.' }); },
    () => choice('Какой знак пишут перед градусами мороза?', 'минус (−)', ['плюс (+)', 'равно (=)', 'никакой'], { explain: 'Градусы мороза записывают со знаком минус.' }),
    () => choice('Что из этого <b>не</b> явление природы?', 'постройка дома', ['гроза', 'листопад', 'ледоход', 'радуга'], { explain: 'Явления природы происходят сами, без человека.' }),
    () => order('Расставь по порядку: что происходит с водой на реке с осени до весны', ['вода остывает', 'ледостав — река замерзает', 'зимой лёд крепкий', 'весной ледоход', 'половодье'], { explain: 'Осенью ледостав, зимой лёд, весной ледоход и половодье.' }),
    () => choice('Почему зимой идёт снег, а летом дождь?', 'зимой холодно, и капли замерзают', ['зимой облака белые', 'летом нет облаков', 'снег тяжелее дождя'], { explain: 'На морозе капли воды в облаках превращаются в снежинки.' }),
    () => multi('Что можно узнать из прогноза погоды?', ['температуру', 'будут ли осадки', 'силу ветра', 'облачность'].slice(0, U.rand(3, 4)), U.pickN(['какой сегодня урок', 'цену хлеба', 'сколько лет бабушке'], 3), { explain: 'Прогноз погоды — температура, осадки, ветер, облачность.' })
  ];

  // ======================================================================
