  const CONST = [['Большая Медведица', 'похожа на ковш из семи звёзд'], ['Малая Медведица', 'на конце её ручки — Полярная звезда'], ['Кассиопея', 'похожа на букву W (или М)'],
    ['Орион', 'охотник с поясом из трёх звёзд'], ['Лебедь', 'похоже на летящую птицу, крест'], ['Лев', 'похоже на лежащего льва']];
  const PLANETS = ['Меркурий', 'Венера', 'Земля', 'Марс', 'Юпитер', 'Сатурн', 'Уран', 'Нептун'];
  const ZODIAC = ['Овен', 'Телец', 'Близнецы', 'Рак', 'Лев', 'Дева', 'Весы', 'Скорпион', 'Стрелец', 'Козерог', 'Водолей', 'Рыбы'];
